/// <reference lib="webworker" />

import Keygen from "./Keygen";

//https://privatekeys.pw/puzzles/bitcoin-puzzle-tx

//40000000000000000:7ffffffffffffffff

let pbkHash = "739437bb3dd6d1983e66629c5f08c70e52769371";

let pvtKeyI = BigInt("0x0000000000000000000000000000000000000000000000040000000000000000");
let pvtKeyF = BigInt("0x000000000000000000000000000000000000000000000007ffffffffffffffff");

let keyGen = new Keygen();

/////////////////////////////////////////////////////////////////////////////////////////////
// Jesus is the Lord!!!
//
//  Setup de número de grids e steps
//
/////////////////////////////////////////////////////////////////////////////////////////////

let grateNumber = 1024 * 1024 * 32;

let cyclesToWait = 2048;


/////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////


globalThis.addEventListener('message', (event) => {
  const { type, data, data2, data3, data4 } = event.data;
  switch (type) {
    case 0:
        let resultRMD = rmd160Search(data);
        postMessage({ type: 0, result: resultRMD });
        break;            
    default:
        postMessage({ error: 'Unknown request type' });
  }
});

/////////////////////////////////////////////////////////
//
//Jesus is The Lord!!!
//
/////////////////////////////////////////////////////////

//Chave inicial = Ponto relativa a primeira chave da serie
let pubKeyGenX: bigint[] = keyGen.keys.eccnP(pvtKeyI, keyGen.keys.Gx, keyGen.keys.Gy);

console.log("pubKeyGenInt: ", pubKeyGenX[0].toString(16))


function rmd160Search (rangeIn: string): string {

    let range = BigInt("0x" + rangeIn) * BigInt(grateNumber);

    let pubKeyGen0 = keyGen.keys.eccnP(pvtKeyI + range, keyGen.keys.Gx, keyGen.keys.Gy);
    let pubKeyGenMn = keyGen.keys.eccnP(((pvtKeyI + pvtKeyF) / 2n) - range, keyGen.keys.Gx, keyGen.keys.Gy);
    let pubKeyGenMp = keyGen.keys.eccnP(((pvtKeyI + pvtKeyF) / 2n) + range + 1n, keyGen.keys.Gx, keyGen.keys.Gy);
    let pubKeyGenF = keyGen.keys.eccnP(pvtKeyF - range, keyGen.keys.Gx, keyGen.keys.Gy);

    let rashPk0 = keyGen.bsvAddRMD160CompPK(pubKeyGen0);
    let rashPkMn = keyGen.bsvAddRMD160CompPK(pubKeyGenMn);
    let rashPkMp = keyGen.bsvAddRMD160CompPK(pubKeyGenMp);
    let rashPkF = keyGen.bsvAddRMD160CompPK(pubKeyGenF);

    if (rashPk0 == pbkHash){
        console.log("colision(0) i: ", range)
        console.log("PVT KEY: ", (pvtKeyI + range).toString(16))
        return ("colision(0) i: " + range + " PVT KEY: " + (pvtKeyI + range).toString(16))
    }
    if (rashPkMn == pbkHash){
        console.log("colision(Mn) -i: ", -range)
        console.log("PVT KEY: ", (((pvtKeyI + pvtKeyF) / 2n) - range).toString(16))
        return ("colision(Mn) -i: " + -range + " PVT KEY: " + (((pvtKeyI + pvtKeyF) / 2n) - range).toString(16))
    }
    if (rashPkMp == pbkHash){
        console.log("colision(Mp) i: ", range)
        console.log("PVT KEY: ", (((pvtKeyI + pvtKeyF) / 2n) + range + 1n).toString(16))
        return ("colision(Mp) i: " + range + " PVT KEY: " + (((pvtKeyI + pvtKeyF) / 2n) + range + 1n).toString(16))
    }
    if (rashPkF == pbkHash){
        console.log("colision -i: ", -range)
        console.log("PVT KEY: ", (pvtKeyF - range).toString(16))
        return ("colision(0) -i: " + -range + " PVT KEY: " + (pvtKeyF - range).toString(16))
    }
   
    //Soma o ponto Delta ao ponto de partida para chegar ao proximo ponto
    for(let i = range; i < (range + BigInt(grateNumber)); i++){

        pubKeyGen0 = keyGen.keys.addp(pubKeyGen0[0], pubKeyGen0[1], keyGen.keys.Gx, keyGen.keys.Gy);

        pubKeyGenMn = keyGen.keys.addp(pubKeyGenMn[0], pubKeyGenMn[1], keyGen.keys.Gx, (keyGen.keys.p - keyGen.keys.Gy));

        pubKeyGenMp = keyGen.keys.addp(pubKeyGenMp[0], pubKeyGenMp[1], keyGen.keys.Gx, keyGen.keys.Gy);

        pubKeyGenF = keyGen.keys.addp(pubKeyGenF[0], pubKeyGenF[1], keyGen.keys.Gx, (keyGen.keys.p - keyGen.keys.Gy));

        rashPk0 = keyGen.bsvAddRMD160CompPK(pubKeyGen0);
        rashPkMn = keyGen.bsvAddRMD160CompPK(pubKeyGenMn);
        rashPkMp = keyGen.bsvAddRMD160CompPK(pubKeyGenMp);
        rashPkF = keyGen.bsvAddRMD160CompPK(pubKeyGenF);
        
        if (rashPk0 == pbkHash){
            console.log("colision(0) i: ", i)
            console.log("PVT KEY: ", (pvtKeyI + range + BigInt(i)).toString(16))
            return ("colision(0) i: " + i + " PVT KEY: " + (pvtKeyI + range + BigInt(i)).toString(16))
        }

        if (rashPkMn == pbkHash){
            console.log("colision(Mn) -i: ", -i)
            console.log("PVT KEY: ", (((pvtKeyI + pvtKeyF) / 2n) - range - BigInt(i)).toString(16))
            return ("colision(Mn) -i: " + -i + " PVT KEY: " + (((pvtKeyI + pvtKeyF) / 2n) + range).toString(16))
        }
        if (rashPkMp == pbkHash){
            console.log("colision(Mp) i: ", i)
            console.log("PVT KEY: ", (((pvtKeyI + pvtKeyF) / 2n) + range + 1n + BigInt(i)).toString(16))
            return ("colision(Mp) i: " + i + " PVT KEY: " + (((pvtKeyI + pvtKeyF) / 2n) + range + 1n + BigInt(i)).toString(16))
        }

        if (rashPkF == pbkHash){
            console.log("colision(F) -i: ", -i)
            console.log("PVT KEY: ", (pvtKeyI - range - BigInt(i)).toString(16))
            return ("colision(F) i: " + -i + " PVT KEY: " + (pvtKeyI - range - BigInt(i)).toString(16))
        }
   
        //Linha de feedback no console
        if(i % BigInt( 16 * cyclesToWait ) == 1n){
            console.log("Point Creating: ", i)
            console.log("RashPK(0): ", rashPk0)
            console.log("PVT KEY(0): ", (pvtKeyI + range + BigInt(i)).toString(16))

            console.log("RashPK(Mn): ", rashPkMn)
            console.log("PVT KEY(Mn): ", (((pvtKeyI + pvtKeyF) / 2n) + range - BigInt(i)).toString(16))

            console.log("RashPK(Mp): ", rashPkMp)
            console.log("PVT KEY(Mp): ", (((pvtKeyI + pvtKeyF) / 2n) + range + 1n + BigInt(i)).toString(16))

            console.log("RashPK(F): ", rashPkF)
            console.log("PVT KEY(F): ", (pvtKeyF - range - BigInt(i)).toString(16))
        }
    }

    return ("colision(0) i: " + 0 + " PVT KEY: " + "00");
};
